app.get("/api/rag/ingest-global", async (req, res) => {
  try {
    const fs2 = await import("fs");
    const path3 = await import("path");
    const filesToIngest = [
      "Smart Charter AI_ Data Ingestion Implementation Guide.md",
      "Authoritative Legal Data Sources for Smart Charter AI RAG.md"
    ];
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) return res.status(500).json({ error: "GEMINI_API_KEY missing" });
    let totalChunks = 0;
    const userStore = getUserStore("system");
    for (const filename of filesToIngest) {
      const filePath = path3.join(process.cwd(), filename);
      if (!fs2.existsSync(filePath)) continue;
      const rawText = fs2.readFileSync(filePath, "utf8");
      const chunks = chunkText(rawText);
      const embeddings = await embedTexts(chunks, apiKey);
      for (let i2 = 0; i2 < chunks.length; i2++) {
        const chunkId = `sys_${filename.replace(/[^a-zA-Z0-9]/g, "_")}_${i2}`;
        const chunkData = {
          id: chunkId,
          text: chunks[i2],
          embedding: embeddings[i2],
          metadata: {
            userId: "system",
            docId: "smart_charter_guides",
            chunkIndex: i2,
            jurisdiction: "Global",
            docType: "Documentation"
          }
        };
        userStore.set(chunkId, chunkData);
      }
      totalChunks += chunks.length;
    }
    res.json({ success: true, totalChunks });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: err.message });
  }
});
